import contextlib
import io
import json
import os
import shutil
import signal
import tempfile

import numpy as np

CAND_FILE = 'block-0.txt'
START_ANCHOR = 'import os'
END_ANCHOR = '    return mega_array'
CASE_TIMEOUT_S = 5


class CaseTimeout(Exception):
    pass


class SetupError(Exception):
    pass


def _alarm(signum, frame):
    raise CaseTimeout()


def load_candidate():
    here = os.path.dirname(os.path.abspath(__file__))
    with open(os.path.join(here, CAND_FILE), encoding='utf-8') as fh:
        full = fh.read()
    start = full.index(START_ANCHOR)
    end = full.index(END_ANCHOR, start) + len(END_ANCHOR)
    ns = {'__name__': 'candidate_module'}
    exec(compile(full[start:end], CAND_FILE, 'exec'), ns)
    return ns['combine_npy_files']


def observe(result):
    if result is None:
        return None
    arr = np.asarray(result)
    shape = [int(d) for d in arr.shape]
    if arr.size == 0:
        rows = []
    elif arr.ndim == 0:
        rows = [[arr.item()]]
    else:
        rows = arr.reshape(-1, arr.shape[-1]).tolist()
    try:
        rows = sorted(rows)
    except TypeError:
        pass
    return {'shape': shape, 'rows_sorted': rows}


def write_inputs(root, payload):
    results_dir = os.path.join(root, 'results')
    os.makedirs(results_dir, exist_ok=True)
    for name, data in (payload.get('files') or {}).items():
        np.save(os.path.join(results_dir, name), np.array(data))
    for name, text in (payload.get('ignored') or {}).items():
        with open(os.path.join(results_dir, name), 'w', encoding='utf-8') as fh:
            fh.write(text)


def run_one(fn, case):
    cid = case.get('id')
    prev = os.getcwd()
    work = None
    try:
        work = tempfile.mkdtemp(prefix='case_', dir=prev)
        write_inputs(work, case.get('input') or {})
        os.chdir(work)
    except Exception as exc:
        os.chdir(prev)
        if work is not None:
            shutil.rmtree(work, ignore_errors=True)
        raise SetupError('%s: %s' % (type(exc).__name__, exc))
    old_handler = signal.signal(signal.SIGALRM, _alarm)
    outcome = None
    try:
        signal.alarm(CASE_TIMEOUT_S)
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            result = fn('results/')
        signal.alarm(0)
        outcome = ('ok', result)
    except CaseTimeout:
        outcome = ('error', 'candidate timed out after %d seconds' % CASE_TIMEOUT_S)
    except Exception as exc:
        outcome = ('error', '%s: %s' % (type(exc).__name__, exc))
    finally:
        signal.alarm(0)
        signal.signal(signal.SIGALRM, old_handler)
        os.chdir(prev)
        shutil.rmtree(work, ignore_errors=True)
    if outcome[0] == 'error':
        return {'id': cid, 'error': outcome[1]}
    return {'id': cid, 'actual': observe(outcome[1])}


def main():
    out = {'results': []}
    try:
        with open(os.path.join(os.getcwd(), 'inputs.json'), encoding='utf-8') as fh:
            cases = json.load(fh)
    except Exception as exc:
        out['harness_error'] = 'could not read inputs.json: %s: %s' % (type(exc).__name__, exc)
        print(json.dumps(out, default=str))
        return
    fn = None
    load_error = None
    try:
        fn = load_candidate()
    except Exception as exc:
        load_error = '%s: %s' % (type(exc).__name__, exc)
    for case in cases:
        cid = case.get('id') if isinstance(case, dict) else None
        if fn is None:
            out['results'].append({'id': cid, 'error': load_error})
            continue
        try:
            out['results'].append(run_one(fn, case))
        except Exception as exc:
            msg = '%s: %s' % (type(exc).__name__, exc)
            out.setdefault('harness_error', msg)
            out['results'].append({'id': cid, 'error': 'harness failure: ' + msg})
    print(json.dumps(out, default=str))


if __name__ == '__main__':
    main()

import json
import os
import io
import shutil
import contextlib
import sys
import numpy as np

ORIGIN = os.getcwd()
NL = chr(10)

def emit(obj):
    sys.stdout.write(json.dumps(obj) + NL)
    sys.stdout.flush()

def load_candidate_source():
    with open(os.path.join(ORIGIN, "block-0.txt"), "r", encoding="utf-8") as f:
        src = f.read()
    start = src.index("import os")
    marker = "return mega_array"
    end = src.index(marker, start) + len(marker)
    return src[start:end] + NL

def build_case_dir(base, idx, inp):
    case_dir = os.path.join(base, "case_" + str(idx))
    shutil.rmtree(case_dir, ignore_errors=True)
    res_dir = os.path.join(case_dir, "results")
    os.makedirs(res_dir)
    for name, rows in (inp.get("files") or {}).items():
        np.save(os.path.join(res_dir, name), np.array(rows, dtype=np.int64))
    for name, text in (inp.get("ignored") or {}).items():
        with open(os.path.join(res_dir, name), "w", encoding="utf-8") as f:
            f.write(text)
    return case_dir

def run_case(fn, case_dir, cid):
    os.chdir(case_dir)
    try:
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            out = fn("results/")
        if not isinstance(out, np.ndarray):
            return {"id": cid, "actual": {"shape": None, "rows_sorted": None, "returned_type": type(out).__name__, "repr": repr(out)[:2000]}}
        rows = out.tolist()
        if isinstance(rows, list):
            try:
                rows_sorted = sorted(rows)
            except TypeError:
                rows_sorted = sorted(rows, key=lambda r: json.dumps(r, sort_keys=True, default=str))
        else:
            rows_sorted = rows
        return {"id": cid, "actual": {"shape": [int(d) for d in out.shape], "rows_sorted": rows_sorted}}
    except Exception as ex:
        return {"id": cid, "error": type(ex).__name__ + ": " + str(ex)}
    finally:
        os.chdir(ORIGIN)

def main():
    results = []
    try:
        with open(os.path.join(ORIGIN, "inputs.json"), "r", encoding="utf-8") as f:
            cases = json.load(f)
        code = load_candidate_source()
        ns = {"__name__": "candidate"}
        exec(compile(code, "candidate.py", "exec"), ns)
        fn = ns["load_npy_files"]
        base = os.path.join(ORIGIN, "_cases")
        os.makedirs(base, exist_ok=True)
    except Exception as ex:
        emit({"results": [], "harness_error": "setup: " + type(ex).__name__ + ": " + str(ex)})
        return
    for idx, case in enumerate(cases):
        cid = case.get("id")
        try:
            case_dir = build_case_dir(base, idx, case.get("input") or {})
        except Exception as ex:
            emit({"results": results, "harness_error": "fixture setup for id " + str(cid) + ": " + type(ex).__name__ + ": " + str(ex)})
            return
        results.append(run_case(fn, case_dir, cid))
    emit({"results": results})

if __name__ == "__main__":
    main()
